Hãy sắp xếp các số ${- \dfrac{2}{3}, - \dfrac{2}{5}, \dfrac{8}{5}, - \dfrac{1}{10}, - \dfrac{4}{3}, - \dfrac{9}{5}}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $30$: $- \dfrac{2}{3} = \dfrac{-20}{30}$; $- \dfrac{2}{5} = \dfrac{-12}{30}$; $\dfrac{8}{5} = \dfrac{48}{30}$; $- \dfrac{1}{10} = \dfrac{-3}{30}$; $- \dfrac{4}{3} = \dfrac{-40}{30}$; $- \dfrac{9}{5} = \dfrac{-54}{30}$.\\
Sắp xếp theo thứ tự tăng dần: $- \dfrac{9}{5}$ < $- \dfrac{4}{3}$ < $- \dfrac{2}{3}$ < $- \dfrac{2}{5}$ < $- \dfrac{1}{10}$ < $\dfrac{8}{5}$.
}\end{ex}

\begin{ex}%[7D1N1]
Hãy sắp xếp các số ${\dfrac{5}{8}, - \dfrac{4}{5}, \dfrac{5}{2}, \dfrac{7}{8}, -1, - \dfrac{7}{5}}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $40$: $\dfrac{5}{8} = \dfrac{25}{40}$; $- \dfrac{4}{5} = \dfrac{-32}{40}$; $\dfrac{5}{2} = \dfrac{100}{40}$; $\dfrac{7}{8} = \dfrac{35}{40}$; $-1 = \dfrac{-40}{40}$; $- \dfrac{7}{5} = \dfrac{-56}{40}$.\\
Sắp xếp theo thứ tự tăng dần: $- \dfrac{7}{5}$ < $-1$ < $- \dfrac{4}{5}$ < $\dfrac{5}{8}$ < $\dfrac{7}{8}$ < $\dfrac{5}{2}$.
}\end{ex}

\begin{ex}%[7D1N1]
Hãy sắp xếp các số ${\dfrac{7}{8}, 1, \dfrac{4}{7}, \dfrac{5}{3}, -4, -2}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $168$: $\dfrac{7}{8} = \dfrac{147}{168}$; $1 = \dfrac{168}{168}$; $\dfrac{4}{7} = \dfrac{96}{168}$; $\dfrac{5}{3} = \dfrac{280}{168}$; $-4 = \dfrac{-672}{168}$; $-2 = \dfrac{-336}{168}$.\\
Sắp xếp theo thứ tự tăng dần: $-4$ < $-2$ < $\dfrac{4}{7}$ < $\dfrac{7}{8}$ < $1$ < $\dfrac{5}{3}$.
}\end{ex}

\begin{ex}%[7D1N1]
Hãy sắp xếp các số ${- \dfrac{6}{7}, 1, 3, \dfrac{9}{2}, 5, -1}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $14$: $- \dfrac{6}{7} = \dfrac{-12}{14}$; $1 = \dfrac{14}{14}$; $3 = \dfrac{42}{14}$; $\dfrac{9}{2} = \dfrac{63}{14}$; $5 = \dfrac{70}{14}$; $-1 = \dfrac{-14}{14}$.\\
Sắp xếp theo thứ tự tăng dần: $-1$ < $- \dfrac{6}{7}$ < $1$ < $3$ < $\dfrac{9}{2}$ < $5$.
}\end{ex}

\begin{ex}%[7D1N1]
Hãy sắp xếp các số ${\dfrac{6}{7}, \dfrac{8}{5}, 1, 5, - \dfrac{8}{3}, - \dfrac{10}{7}}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $105$: $\dfrac{6}{7} = \dfrac{90}{105}$; $\dfrac{8}{5} = \dfrac{168}{105}$; $1 = \dfrac{105}{105}$; $5 = \dfrac{525}{105}$; $- \dfrac{8}{3} = \dfrac{-280}{105}$; $- \dfrac{10}{7} = \dfrac{-150}{105}$.\\
Sắp xếp theo thứ tự tăng dần: $- \dfrac{8}{3}$ < $- \dfrac{10}{7}$ < $\dfrac{6}{7}$ < $1$ < $\dfrac{8}{5}$ < $5$.
}\end{ex}

\begin{ex}%[7D1N1]
Hãy sắp xếp các số ${\dfrac{7}{10}, 1, 2, \dfrac{7}{3}, -1, - \dfrac{4}{3}}$ theo thứ tự tăng dần.
\loigiai{
Quy đồng các số về cùng mẫu dương $30$: $\dfrac{7}{10} = \dfrac{21}{30}$; $1 = \dfrac{30}{30}$; $2 = \dfrac{60}{30}$; $\dfrac{7}{3} = \dfrac{70}{30}$; $-1 = \dfrac{-30}{30}$; $- \dfrac{4}{3} = \dfrac{-40}{30}$.\\
Sắp xếp theo thứ tự tăng dần: $- \dfrac{4}{3}$ < $-1$ < $\dfrac{7}{10}$ < $1$ < $2$ < $\dfrac{7}{3}$.
}\end{ex}
